            background-color: rgba(255, 255, 255, 0.85);
        }

        .avatar {
            width: clamp(36px, 8vw, 40px);
            height: clamp(36px, 8vw, 40px);
            border-radius: 50%;
            margin-right: clamp(8px, 2vw, 12px);
            flex-shrink: 0;
        }

        .message-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: 4px;
            padding-right: clamp(28px, 7vw, 32px);
            min-width: 0;
        }

        .message-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 2px;
            width: 100%;
        }

        .message-title {
            font-size: clamp(13px, 3.5vw, 15px);
            color: #333;
            font-weight: 700;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
            flex: 1;
        }

        .message-time {
            font-size: clamp(10px, 2.8vw, 12px);
            color: #999;
            flex-shrink: 0;
            margin-left: clamp(6px, 1.5vw, 8px);
        }

        .message-subtitle {
            font-size: clamp(12px, 3.2vw, 14px);
            color: #666;
            line-height: 1.4;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
            width: 100%;
