        // 获取随机默认头像
        function getRandomDefaultAvatar() {
            const randomIndex = Math.floor(Math.random() * defaultAvatars.length);
            return defaultAvatars[randomIndex];
        }

        // 获取头像URL的函数
        function getAvatarUrl(msg) {
            if (msg.type === '群聊') {
                return channelAvatars[msg.channel] || getRandomDefaultAvatar();
            } else {
                // 如果是私聊，尝试匹配角色头像（不区分大小写）
                const characterName = msg.channel.toLowerCase();
                const matchedCharacter = Object.keys(characterAvatars).find(
                    name => name.toLowerCase() === characterName
                );
                return matchedCharacter ? characterAvatars[matchedCharacter] : getRandomDefaultAvatar();
            }
        }

        // 消息数据
        const messagesData = `$1`;

        // 解析消息函数
        function parseMessages(data) {
            return data.trim().split('\n').map(line => {
                const [type, channel, content, time, count] = line.split('|');
                return { type, channel, content, time, count: parseInt(count) };
            });
        }

        // 渲染消息列表
        function renderMessages() {
            const messages = parseMessages(messagesData);
            const messageList = document.querySelector('.message-list');
            messageList.innerHTML = messages.map(msg => `
                <div class="message-item" data-type="${msg.type}">
                    <img src="${getAvatarUrl(msg)}" class="avatar">
                    <div class="message-content">
                        <div class="message-header">
                            <div class="message-title">${msg.channel}</div>
                            <div class="message-time">${msg.time}</div>
                        </div>
                        <div class="message-subtitle">${msg.content}</div>
                    </div>
                    ${msg.count > 0 ? `<span class="notification-badge">${msg.count}</span>` : ''}
                </div>
            `).join('');

            // 添加点击事件监听
            const messageItems = document.querySelectorAll('.message-item');
            messageItems.forEach(item => {
                item.addEventListener('click', function() {
                    const type = this.dataset.type;
                    const channel = this.querySelector('.message-title').textContent;

                    if (type === '群聊') {
                        triggerSlash(`/send 进入群聊(群聊名称:${channel})`);
                    } else if (type === '私聊') {
                        triggerSlash(`/send 进入私聊(私聊对象:${channel})`);
                    }
                });
            });
        }

