        function initializeMemberSelects() {
            const selects = document.querySelectorAll('.member-select');
            selects.forEach(select => {
                if (select.options.length <= 1) {  // 只有默认选项时才添加
                    // 获取所有角色名称
                    const characters = Object.keys(characterAvatars);

                    // 按字母顺序排序
                    characters.sort();

                    // 添加选项
                    characters.forEach(character => {
                        const option = document.createElement('option');
                        option.value = character;
                        option.textContent = character;
                        select.appendChild(option);
                    });
                }
            });
        }

        function addMemberRow() {
            const container = document.getElementById('memberContainer');
            const row = document.createElement('div');
            row.className = 'member-row';
            row.innerHTML = `
                <select class="member-select">
                    <option value="">请选择舰娘</option>
                </select>
                <button class="remove-member-btn">删除</button>
            `;
            container.appendChild(row);

            // 初始化新添加的选择框
            initializeMemberSelects();

            // 添加删除按钮事件
            const removeBtn = row.querySelector('.remove-member-btn');
            removeBtn.addEventListener('click', () => row.remove());
        }

        function handleCreateGroup() {
            const groupName = document.getElementById('groupNameInput').value.trim();
            const members = Array.from(document.querySelectorAll('.member-select'))
                .map(select => select.value)
                .filter(value => value);

            if (!groupName) {
                alert('请输入群聊名称');
                return;
            }

            if (members.length < 2) {
                alert('请至少选择两名成员');
                return;
            }

            // 构建新的命令格式
            const command = `action: 创建群聊\nname: ${groupName}\nmembers:\n${members.join('\n')}`;
            triggerSlash(`/send ${command}`);
            hideCreateGroupModal();
        }

