        .question-icon, .help-icon {
            width: clamp(16px, 5vw, 20px);
            height: clamp(16px, 5vw, 20px);
            opacity: 1;
            cursor: pointer;
            transition: transform 0.2s ease;
        }

        .question-icon:hover, .help-icon:hover {
            transform: scale(1.1);
        }

        .question-icon img, .help-icon img {
            width: 100%;
            height: 100%;
            object-fit: contain;
        }

        .question-icon img {
            filter: brightness(0) invert(1);
        }

        .help-icon img {
            filter: brightness(0) saturate(129%) invert(192%) sepia(85%)
                    saturate(1498%) hue-rotate(194deg) brightness(139%) contrast(101%);
        }

        /* 聊天容器 */
        .chat-container {
            height: 480px;
            background-color: #ecf4f4;
            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
        }

        /* 消息列表容器 */
        .messages-container {
            flex: 1;
            overflow-y: auto;
            padding: 10px;
            box-sizing: border-box;
            scrollbar-width: none; /* Firefox */
            -ms-overflow-style: none; /* IE and Edge */
            min-height: 0;
            position: relative;
            z-index: 1;
        }

        /* 隐藏 Webkit 浏览器的滚动条 */
        .messages-container::-webkit-scrollbar {
            display: none;
        }

        /* 移除旧的滚动条样式 */
        .messages-container::-webkit-scrollbar-track {
            display: none;
        }

        .messages-container::-webkit-scrollbar-thumb {
            display: none;
        }

        /* 标题栏容器 */
        .chat-header {
            background: rgba(255, 255, 255, 0.85);
            padding: clamp(4px, 1.5vw, 6px) clamp(8px, 3vw, 12px);
            border-radius: 10px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            box-shadow: 0 1px 2px rgba(0,0,0,0.05);
            margin: 10px 10px 0 10px;
            flex-shrink: 0;
            position: relative; /* 为弹窗定位提供参考点 */
            transition: background-color 0.2s ease; /* 添加过渡效果 */
        }

        .chat-header:hover {
            background: rgba(255, 255, 255, 0.95); /* 悬停时轻微变亮 */
        }

        /* 状态栏弹窗 */
        .status-popup {
            position: absolute;
            top: 100%;
            left: 0;
            right: 0;
            background: rgba(255, 255, 255, 0.95);
            border-radius: 0 0 10px 10px;
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
            padding: 15px;
            z-index: 100;
            display: none;
            margin: 0 10px;
            animation: slideDown 0.3s ease-out;
            transform-origin: top center;
        }

        @keyframes slideDown {
            from { transform: scaleY(0); opacity: 0; }
            to { transform: scaleY(1); opacity: 1; }
        }

        /* 状态栏内容布局 */
        .status-content {
            display: flex;
            align-items: center;
            margin-bottom: 12px;
        }

        /* 角色头像样式 */
        .character-avatar {
            width: 50px;
            height: 50px;
