        /* 摄像头状态指示器 */
        .camera-status {
            display: flex;
            justify-content: space-between;
            margin-bottom: 10px;
            align-items: center;
        }

        /* 分组状态样式 */
        .camera-status-group {
            margin-bottom: 15px;
