            padding: clamp(6px, 2vw, 10px); /* 减小默认内边距 */
            border-radius: 8px;
            font-size: clamp(11px, 3vw, 13px); /* 减小默认字体大小 */
            color: #767474;  /* 保持指定的颜色 */
