            box-shadow: 0 2px 8px rgba(0, 191, 255, 0.15);
        }

        .message.player-message .message-bubble::before {
            background-color: #00BFFF;
        }

        /* 玩家后续消息的气泡样式 */
        .message.player-message.follow-up .message-bubble {
            max-width: min(500px, calc(100% - 20px));
