            .move-up-button {
                left: calc(50% - 80px);
            }

            .move-down-button {
                left: calc(50% - 40px);
            }

            .zoom-out-button {
                left: calc(50% + 0px);
            }

            .zoom-in-button {
                left: calc(50% + 40px);
            }

            .rotate-button {
                left: calc(50% + 80px);
            }
        }

        /* 触屏设备优化 */
        @media (hover: none) and (pointer: coarse) {
            .rotate-button, .zoom-in-button, .zoom-out-button, .move-up-button, .move-down-button {
                width: 48px; /* 触屏设备按钮更大，便于点击 */
