            .rotate-button svg, .zoom-in-button svg, .zoom-out-button svg, .move-up-button svg, .move-down-button svg {
                width: 28px;
                height: 28px;
            }
        }

        /* 状态指示器区域样式 */
        .camera-status-section {
            margin-top: 10px;
            border-top: 1px solid rgba(0, 0, 0, 0.1);
            padding-top: 10px;
        }

        .camera-status-title {
            font-size: 14px;
            font-weight: 600;
            color: #333;
            margin-bottom: 8px;
        }

        /* 摄像头状态指示器 */
        .camera-status {
            display: flex;
