        }

        .status-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            margin-right: 6px;
            background-color: currentColor;
        }

        /* 开启状态样式 */
        .status-on {
            background-color: rgba(76, 217, 100, 0.15);
