                        border-radius: 20px;
                        font-size: 14px;
                        z-index: 2002;
                        opacity: 0;
                        transition: opacity 0.3s ease;
                    `;
                    hint.textContent = text;
                    document.body.appendChild(hint);

                    // 淡入淡出效果显示提示
            setTimeout(() => {
                        hint.style.opacity = '1';
                        setTimeout(() => {
                            hint.style.opacity = '0';
