                document.addEventListener('mouseup', () => {
                    if (zoomIntervalId !== null) {
                        clearInterval(zoomIntervalId);
                        zoomIntervalId = null;
                    }
                    if (moveIntervalId !== null) {
                        clearInterval(moveIntervalId);
                        moveIntervalId = null;
                    }
                });

                // 监听鼠标离开按钮事件，停止缩放
                zoomInButton.addEventListener('mouseleave', () => {
                    if (zoomIntervalId !== null) {
