                    // 判断当前消息是否为玩家(我方)消息
                    const isPlayerMessage = message.isPlayer === true;

                    // 判断是否是同一组消息的后续消息
                    // 需考虑玩家消息和NPC消息分开处理
                    const isFollowUp = message.username === currentUsername && 
                                      message.isPartOfGroup === true && 
                                      !message.isFirstInGroup;

                    // 设置全局标志，用于滚动动画优化
                    isProcessingFollowUp = isFollowUp;

