        /* 加载界面样式 */
        .loading-container {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.8);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            z-index: 9999;
        }

        .loading-icon {
            width: 80px;
            height: 80px;
            margin-bottom: 20px;
            animation: flip 1.5s infinite;
            transform-style: preserve-3d;
        }

        .loading-icon img {
            width: 100%;
            height: 100%;
            object-fit: contain;
        }

        @keyframes flip {
            0% {
                transform: rotateY(0deg) translateZ(1px);
            }
            50% {
                transform: rotateY(180deg) translateZ(1px);
            }
            100% {
                transform: rotateY(360deg) translateZ(1px);
            }
        }

        .loading-progress {
            width: 200px;
