        }

        .loading-text {
            margin-top: 15px;
            color: white;
            font-size: 16px;
            text-align: center;
        }

        /* 图片文本消息样式 */
        .image-text-container {
            position: relative;
            background: #ffffff;
            padding: 12px 18px;
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.3s ease;
            max-width: 260px;
