        .image-text-preview {
            color: #666;
            font-size: 14px;
            display: flex;
            align-items: center;
            gap: 6px;
            white-space: nowrap;  /* 防止文本换行 */
            overflow: hidden;     /* 防止内容溢出 */
            text-overflow: ellipsis;  /* 如果文字太长，显示省略号 */
        }

        .image-text-preview svg {
            width: 16px;
            height: 16px;
            fill: #666;
            flex-shrink: 0;  /* 防止SVG图标被压缩 */
        }

        /* 响应式设计：针对不同屏幕尺寸优化图片预览显示 */
        @media screen and (max-width: 480px) {
