            transition: transform 0.3s ease; /* 平滑过渡效果 */
        }

        /* 专门针对旋转后的横屏图片 */
        .detail-image.rotated-landscape {
            max-height: none !important;
            max-width: calc(100vh - 200px) !important;
        }

        .detail-text {
            width: 100%;
            margin-bottom: 20px;
