        // 获取随机默认头像
        function getRandomDefaultAvatar() {
            const randomIndex = Math.floor(Math.random() * defaultAvatars.length);
            return defaultAvatars[randomIndex];
        }

        // 获取头像URL的函数
        function getAvatarUrl(msg) {
            if (msg.type === '群聊') {
                return channelAvatars[msg.channel] || getRandomDefaultAvatar();
            } else {
                // 如果是私聊，尝试匹配角色头像（不区分大小写）
                const characterName = msg.channel.toLowerCase();
                const matchedCharacter = Object.keys(characterAvatars).find(
                    name => name.toLowerCase() === characterName
                );
                return matchedCharacter ? characterAvatars[matchedCharacter] : getRandomDefaultAvatar();
            }
        }

        // 消息数据
        const messagesData = `$1`;

        // 解析消息函数
        function parseMessages(data) {
            return data.trim().split('\n').map(line => {
                const [type, channel, content, time, count] = line.split('|');
                return { type, channel, content, time, count: parseInt(count) };
            });
        }

        // 渲染消息列表
        function renderMessages() {
            const messages = parseMessages(messagesData);
            const messageList = document.querySelector('.message-list');
            messageList.innerHTML = messages.map(msg => `
                <div class="message-item" data-type="${msg.type}">
                    <img src="${getAvatarUrl(msg)}" class="avatar">
                    <div class="message-content">
                        <div class="message-header">
                            <div class="message-title">${msg.channel}</div>
                            <div class="message-time">${msg.time}</div>
                        </div>
                        <div class="message-subtitle">${msg.content}</div>
                    </div>
                    ${msg.count > 0 ? `<span class="notification-badge">${msg.count}</span>` : ''}
                </div>
            `).join('');

            // 添加点击事件监听
            const messageItems = document.querySelectorAll('.message-item');
            messageItems.forEach(item => {
                item.addEventListener('click', function() {
                    const type = this.dataset.type;
                    const channel = this.querySelector('.message-title').textContent;

                    if (type === '群聊') {
                        triggerSlash(`/send 进入群聊(群聊名称:${channel})`);
                    } else if (type === '私聊') {
                        triggerSlash(`/send 进入私聊(私聊对象:${channel})`);
                    }
                });
            });
        }

        // 弹窗相关函数
        function showModal() {
            const modal = document.getElementById('chatModal');
            modal.style.display = 'flex';
        }

        function hideModal() {
            const modal = document.getElementById('chatModal');
            modal.style.display = 'none';
        }

        // 输入框相关函数
        let currentInputType = '';

        function showInputModal(type, title) {
            currentInputType = type;
            const inputModal = document.getElementById('inputModal');
            const inputTitle = document.getElementById('inputTitle');
            const inputField = document.getElementById('inputField');

            inputTitle.textContent = title;
            inputField.value = '';
            inputField.placeholder = type === 'group' ? '请输入群聊名称' : '请输入角色名称';
            inputModal.style.display = 'flex';
            inputField.focus();
        }

        function hideInputModal() {
            const inputModal = document.getElementById('inputModal');
            inputModal.style.display = 'none';
        }

        function handleInput(value) {
            if (!value.trim()) return;

            if (currentInputType === 'group') {
                triggerSlash(`/send 进入群聊(群聊名称:${value.trim()})`);
            } else if (currentInputType === 'private') {
                triggerSlash(`/send 进入私聊(私聊对象:${value.trim()})`);
            }
            hideInputModal();
        }

        // 创建群聊相关函数
        function showCreateGroupModal() {
            const modal = document.getElementById('createGroupModal');
            modal.style.display = 'flex';

            // 初始化舰娘选择列表
            initializeMemberSelects();
        }

        function hideCreateGroupModal() {
            const modal = document.getElementById('createGroupModal');
            modal.style.display = 'none';
        }

        function initializeMemberSelects() {
            const selects = document.querySelectorAll('.member-select');
            selects.forEach(select => {
                if (select.options.length <= 1) {  // 只有默认选项时才添加
                    // 获取所有角色名称
                    const characters = Object.keys(characterAvatars);

                    // 按字母顺序排序
                    characters.sort();

                    // 添加选项
                    characters.forEach(character => {
                        const option = document.createElement('option');
                        option.value = character;
                        option.textContent = character;
                        select.appendChild(option);
                    });
                }
            });
        }

        function addMemberRow() {
            const container = document.getElementById('memberContainer');
            const row = document.createElement('div');
            row.className = 'member-row';
            row.innerHTML = `
                <select class="member-select">
                    <option value="">请选择舰娘</option>
                </select>
                <button class="remove-member-btn">删除</button>
            `;
            container.appendChild(row);

            // 初始化新添加的选择框
            initializeMemberSelects();

            // 添加删除按钮事件
            const removeBtn = row.querySelector('.remove-member-btn');
            removeBtn.addEventListener('click', () => row.remove());
        }

        function handleCreateGroup() {
            const groupName = document.getElementById('groupNameInput').value.trim();
            const members = Array.from(document.querySelectorAll('.member-select'))
                .map(select => select.value)
                .filter(value => value);

            if (!groupName) {
                alert('请输入群聊名称');
                return;
            }

            if (members.length < 2) {
                alert('请至少选择两名成员');
                return;
            }

            // 构建新的命令格式
            const command = `action: 创建群聊\nname: ${groupName}\nmembers:\n${members.join('\n')}`;
            triggerSlash(`/send ${command}`);
            hideCreateGroupModal();
        }

