        // 资源预加载器类
        class ResourcePreloader {
            constructor() {
                this.totalResources = 0;
                this.loadedResources = 0;
                this.resources = new Map();
                this.progressBar = document.querySelector('.progress-bar');
                this.loadingText = document.querySelector('.loading-text');
                this.loadingMessages = [
                    { progress: 0, message: "正在启动JUUSTAGRAM..." },
                    { progress: 15, message: "正在连接舰娘通讯网络..." },
                    { progress: 30, message: "正在呼叫指挥官..." },
                    { progress: 45, message: "正在整理港区信息..." },
                    { progress: 60, message: "正在收集舰娘们的可爱照片..." },
                    { progress: 75, message: "正在准备消息列表..." },
                    { progress: 90, message: "马上就好啦，指挥官！" },
                    { progress: 100, message: "欢迎回来，指挥官！" }
                ];
            }

            addResource(url, type) {
                if (!this.resources.has(url)) {
                    this.resources.set(url, { type, loaded: false });
                    this.totalResources++;
                }
            }

            updateProgress() {
                const progress = (this.loadedResources / this.totalResources) * 100;
                this.progressBar.style.width = `${progress}%`;

                // 根据当前进度选择合适的消息
                const currentMessage = this.loadingMessages.reduce((prev, curr) => {
                    return (progress >= curr.progress) ? curr : prev;
                }, this.loadingMessages[0]);

                this.loadingText.textContent = currentMessage.message;
            }

            async preloadResource(url, type) {
                try {
                    if (type === 'image') {
                        await this.preloadImage(url);
                    }
                    this.loadedResources++;
                    this.resources.get(url).loaded = true;
                    this.updateProgress();
                } catch (error) {
                    console.error(`无法加载资源: ${url}`, error);
                    this.loadedResources++;
                    this.updateProgress();
                }
            }

            preloadImage(url) {
                return new Promise((resolve, reject) => {
                    const img = new Image();
                    img.onload = () => resolve();
                    img.onerror = () => reject();
                    img.src = url;
                });
            }

            async preloadAll() {
                const loadPromises = [];
                for (const [url, { type }] of this.resources) {
                    loadPromises.push(this.preloadResource(url, type));
                }
                await Promise.all(loadPromises);

                // 所有资源加载完成后
                document.getElementById('loading-screen').style.display = 'none';
                return true;
            }
        }

        // 获取需要预加载的图片URL
        function getRequiredImageUrls() {
            const messages = parseMessages(messagesData);
            const requiredUrls = new Set();

            messages.forEach(msg => {
                const avatarUrl = msg.type === '群聊' 
                    ? channelAvatars[msg.channel] 
                    : characterAvatars[msg.channel] || getRandomDefaultAvatar();

                if (avatarUrl) requiredUrls.add(avatarUrl);
            });

            // 添加顶部栏图标
            requiredUrls.add("https://files.catbox.moe/d33q3q.png");
            requiredUrls.add("https://files.catbox.moe/xps1qc.png");

            return Array.from(requiredUrls);
        }

        // 初始化函数
        async function initializeApp() {
            const preloader = new ResourcePreloader();

            // 添加需要预加载的资源
            const imageUrls = getRequiredImageUrls();
            imageUrls.forEach(url => preloader.addResource(url, 'image'));

            // 开始预加载
            await preloader.preloadAll();

            // 渲染消息列表
            renderMessages();
        }

        // 页面加载完成后初始化
        document.addEventListener('DOMContentLoaded', () => {
            initializeApp();

            // 添加问号图标点击事件
            const topicsButton = document.getElementById('topicsButton');
            topicsButton.addEventListener('click', showModal);

            // 添加弹窗点击事件
            const modal = document.getElementById('chatModal');
            modal.addEventListener('click', (e) => {
                if (e.target === modal) {
                    hideModal();
                }
            });

            // 修改按钮点击事件
            document.getElementById('startPrivateChat').addEventListener('click', () => {
                hideModal();
                showInputModal('private', '请输入私聊对象名称');
            });

            document.getElementById('startGroupChat').addEventListener('click', () => {
                hideModal();
                showInputModal('group', '请输入群聊名称');
            });

            // 添加输入框事件监听
            document.getElementById('cancelInput').addEventListener('click', hideInputModal);

            document.getElementById('confirmInput').addEventListener('click', () => {
                const inputValue = document.getElementById('inputField').value;
                handleInput(inputValue);
            });

            document.getElementById('inputField').addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    const inputValue = e.target.value;
                    handleInput(inputValue);
                }
            });

            // 点击输入框外部关闭
            document.getElementById('inputModal').addEventListener('click', (e) => {
                if (e.target === document.getElementById('inputModal')) {
                    hideInputModal();
                }
            });

            // 修改创建群聊按钮事件
            document.getElementById('createGroup').addEventListener('click', () => {
                hideModal();
                showCreateGroupModal();
            });

            // 添加创建群聊相关事件监听
            document.getElementById('addMemberBtn').addEventListener('click', addMemberRow);
            document.getElementById('cancelCreateGroup').addEventListener('click', hideCreateGroupModal);
            document.getElementById('confirmCreateGroup').addEventListener('click', handleCreateGroup);

            // 初始化删除按钮事件
            document.querySelectorAll('.remove-member-btn').forEach(btn => {
                btn.addEventListener('click', () => btn.parentElement.remove());
            });

            // 点击模态框外部关闭
            document.getElementById('createGroupModal').addEventListener('click', (e) => {
                if (e.target === document.getElementById('createGroupModal')) {
                    hideCreateGroupModal();
                }
            });

            // 添加退出按钮事件
            document.querySelector('.help-icon').addEventListener('click', showExitModal);

            // 添加退出确认事件
            document.getElementById('confirmExit').addEventListener('click', handleExit);
            document.getElementById('cancelExit').addEventListener('click', hideExitModal);

            // 点击模态框外部关闭
            document.getElementById('exitModal').addEventListener('click', (e) => {
                if (e.target === document.getElementById('exitModal')) {
                    hideExitModal();
                }
            });
