        /* 添加叙事消息样式 */
        .narration-bubble {
            background-color: #dcecfc;
            padding: clamp(8px, 2.5vw, 15px);
            border-radius: 12px;
            font-size: clamp(12px, 3.5vw, 14px);
            color: #666;
            box-shadow: 0 1px 2px rgba(0,0,0,0.05);
            text-align: left;
            margin: 6px auto;
            max-width: 80%;
            line-height: 1.6;
            font-family: "Noto Sans SC", "Source Han Sans SC", "Microsoft YaHei", sans-serif;
