        }

        .narration-segment:last-child {
            margin-bottom: 0;
        }

        /* 添加媒体查询以确保在不同屏幕尺寸下的响应式居中 */
        @media screen and (max-width: 768px) {
            .narration-bubble {
                max-width: 90%;
