            animation: slideIn 0.3s ease; /* Use existing animation */
        }

        .exit-confirm-content p {
            margin: 0 0 20px 0;
            font-size: 16px;
            color: #333;
            font-weight: 500;
        }

        .exit-confirm-buttons {
            display: flex;
            justify-content: space-between;
            gap: 15px;
        }

        .exit-confirm-buttons button {
            flex: 1;
            border: none;
            padding: 10px;
            border-radius: 8px;
