                let currentScale = 1;
                // 当前Y轴位移值（上下移动），单位像素
                let currentYPosition = 0;
                // 缩放步长
                const scaleStep = 0.05;
                // 移动步长
                const moveStep = 10;
                // 缩放范围限制
                const minScale = 0.5;
                const maxScale = 3;
                // 移动范围限制（像素）
                const maxYMove = 300;
