                    // 更新旋转角度
                    currentRotation = (currentRotation + 90) % 360;

                    // 应用旋转
                    updateImageTransform();

                    // 更新旋转按钮状态
                    rotateButton.setAttribute('data-rotation', currentRotation.toString());

                    // 根据旋转角度调整图片适应方式
                    if (currentRotation === 90 || currentRotation === 270) {
