            for (const character in avatarMap) {
                if (chatTitle.includes(character)) {
                    return character;
                }
            }

            // 如果找不到匹配角色，返回默认角色或第一个角色
            return Object.keys(avatarMap)[0]; // 返回第一个角色作为默认
