        .status-indicator:hover {
            background: rgba(0, 0, 0, 0.1);
        }

        .status-indicator svg {
            width: 16px;
            height: 16px;
            margin-right: 4px;
        }

        .status-text {
            font-size: 12px;
            font-weight: 500;
        }

        .status-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            margin-right: 6px;
            background-color: currentColor;
        }

        /* 开启状态样式 */
        .status-on {
            background-color: rgba(76, 217, 100, 0.15);
            border-color: rgba(76, 217, 100, 0.3);
        }

        .status-on:hover {
            background-color: rgba(76, 217, 100, 0.25);
        }

        .status-on svg {
            fill: #4CD964;
        }

        .status-on .status-text {
            color: #4CD964;
        }

        .status-on .status-dot {
            background-color: #4CD964;
            box-shadow: 0 0 5px rgba(76, 217, 100, 0.5);
        }

        /* 关闭状态样式 */
        .status-off {
            background-color: rgba(255, 59, 48, 0.15);
            border-color: rgba(255, 59, 48, 0.3);
        }

        .status-off:hover {
            background-color: rgba(255, 59, 48, 0.25);
        }

        .status-off svg {
            fill: #FF3B30;
        }

        .status-off .status-text {
            color: #FF3B30;
        }

        .status-off .status-dot {
            background-color: #FF3B30;
            box-shadow: 0 0 5px rgba(255, 59, 48, 0.5);
        }

        /* 交互模块特殊样式 */
        .camera-status:last-child .status-indicator {
            min-width: 70px;
            justify-content: center;
        }

        /* [NEW] Exit Confirmation Modal Styles */
        .exit-confirm-modal {
            display: none; /* Hidden by default */
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.6);
            z-index: 3000;
            justify-content: center;
            align-items: center;
            backdrop-filter: blur(2px);
        }

        .exit-confirm-modal.active {
            display: flex;
        }

        .exit-confirm-content {
            background: white;
            padding: 25px 30px;
            border-radius: 12px;
            box-shadow: 0 5px 15px rgba(0,0,0,0.3);
            text-align: center;
            width: 80%;
            max-width: 300px;
            animation: slideIn 0.3s ease; /* Use existing animation */
        }

        .exit-confirm-content p {
            margin: 0 0 20px 0;
            font-size: 16px;
            color: #333;
            font-weight: 500;
        }

        .exit-confirm-buttons {
            display: flex;
            justify-content: space-between;
            gap: 15px;
        }

        .exit-confirm-buttons button {
            flex: 1;
            border: none;
            padding: 10px;
            border-radius: 8px;
            font-size: 14px;
            font-weight: bold;
            cursor: pointer;
            transition: opacity 0.2s, transform 0.1s;
        }

        .exit-confirm-buttons button:hover {
            opacity: 0.85;
        }

        .exit-confirm-buttons button:active {
            transform: scale(0.95);
        }

        .exit-button-yes {
            background-color: #00BFFF; /* Blue button */
            color: white;
        }

        .exit-button-no {
            background-color: #FF3B30; /* Red button */
            color: white;
        }
    </style>
</head>
