            // Function to execute when user confirms exit
            async function executeExitAction() {
                const LOREBOOK_NAME = "长门";
                const TARGET_POSITION = 'at_depth_as_system';
                const TARGET_DEPTH = 0;
                const TARGET_ORDER = 999;
                let targetEntryUid = null;

                try {
                    // These functions (getLorebooks, etc.) are assumed to be provided by the environment (e.g., SillyTavern)
                    if (typeof getLorebooks !== 'function' || typeof getLorebookEntries !== 'function' || typeof setLorebookEntries !== 'function') {
                        console.error('Lorebook API functions are not available.');
                        // Fallback or error message could be shown to the user here
                        return;
                    }

                    // 1. Find the lorebook and the specific entry
                    const lorebooks = await getLorebooks();
                    if (!lorebooks.includes(LOREBOOK_NAME)) {
                        console.error(`Lorebook "${LOREBOOK_NAME}" not found.`);
                        return;
                    }

                    const entries = await getLorebookEntries(LOREBOOK_NAME, {
                        filter: { position: TARGET_POSITION, depth: TARGET_DEPTH, order: TARGET_ORDER },
                        fields: ['uid'] // We only need the UID to modify it
                    });

                    if (entries.length > 0) {
                        targetEntryUid = entries[0].uid;
                    } else {
                        console.error(`Entry not found in "${LOREBOOK_NAME}" (@D${TARGET_DEPTH}, order ${TARGET_ORDER}).`);
